import { DataCollection } from '@wix/wix-ui-icons-common/lazy';

import type { AddButton, AddButtonsCreator } from './../ricos-types/index.js';
import { Node_Type } from './../ricos-types/index.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';

import { INSERT_TABLE_BUTTON, INSERT_TABLE_MODAL_ADD_BUTTON } from './data-hooks.js';
import { InsertModal } from './modals/insert-modal.js';
import type { TablePluginEditorConfig } from './types.js';
import { INSERT_TABLE_MODAL_ID } from './types.js';

export const toolbarsToAddIn: (TOOLBARS.MOBILE | TOOLBARS.FOOTER | TOOLBARS.SIDE)[] = [
  TOOLBARS.FOOTER,
  TOOLBARS.SIDE,
  TOOLBARS.MOBILE,
];

export const getAddButtons: AddButtonsCreator<TablePluginEditorConfig> = (
  _,
  services
): AddButton[] => {
  const {
    modals,
    context: { isMobile },
  } = services;

  return [
    {
      id: Node_Type.TABLE,
      label: INSERT_PLUGIN_BUTTONS.TABLE,
      dataHook: INSERT_TABLE_BUTTON,
      icon: DataCollection,
      tooltip: 'TablePlugin_InsertButton_Tooltip',
      toolbars: [TOOLBARS.MOBILE, TOOLBARS.FOOTER, TOOLBARS.SIDE],
      command: ({ referenceElement }) => {
        modals?.togglePluginPanel({
          id: INSERT_TABLE_MODAL_ID,
          Component: InsertModal,
          componentProps: {},
          isMobile,
          initialFocus: `[data-hook="${INSERT_TABLE_MODAL_ADD_BUTTON}"]`,
          positioning: {
            referenceElement,
            placement: 'bottom',
          },
          mobileLayout: 'drawer',
        });

        return true;
      },
      menuConfig: {
        tags: 'Table_plugin_search_tags',
        group: 'advanced',
      },
    },
  ];
};
