import type { PmNodeConverter, PmNodeJson } from './../pm-converters/types.js';
import { TIPTAP_TABLE_HEADER_CELL_TYPE } from './../ricos-content/index.js';
import type { Node, TableCellData, TableData } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { TableCellNode, TableNode, TableRowNode } from './../ricos-schema/next-schema/index.js';

import { TABLE_DEFAULTS, normalizePadding } from './defaults.js';

export const tableConverter: PmNodeConverter = {
  toPm: {
    types: [Node_Type.TABLE],
    // @ts-ignore next node type
    convert: (node: TableNode, visit: (node: TableRowNode | TableCellNode) => PmNodeJson[]) => {
      // animation is hoisted to a top-level attr so the shared animation panel
      // reads/writes one uniform attr across all node types
      const { dimensions, cellPadding, animation, ...restTableData } = node.tableData || {};
      const { colsWidthRatio, colsMinWidth } = node.tableData?.dimensions || {};
      const widthInPixel = ratioWidthToPixel(colsWidthRatio, colsMinWidth);

      // Build a grid map to resolve visual column positions accounting for rowspan
      const rows = node.nodes || [];
      const gridOccupied: boolean[][] = rows.map(() => []);

      return {
        type: Node_Type.TABLE,
        attrs: {
          id: node.id,
          dimensions,
          animation: animation ?? null,
          tableData: {
            ...restTableData,
            cellPadding: normalizePadding(cellPadding, [...TABLE_DEFAULTS.cellPadding]),
          },
        },
        content: rows.map((rowNode, rowIndex) => {
          let colIdx = 0;

          return {
            type: Node_Type.TABLE_ROW,
            attrs: { id: rowNode.id, height: node.tableData?.dimensions?.rowsHeight?.[rowIndex] },
            content: ((rowNode.nodes || []) as TableCellNode[]).map(colNode => {
              const colspan = colNode.tableCellData?.colspan || 1;
              const rowspan = colNode.tableCellData?.rowspan || 1;

              // Skip columns occupied by rowspan from previous rows
              while (gridOccupied[rowIndex]?.[colIdx]) {
                colIdx++;
              }
              const visualCol = colIdx;

              // Mark grid cells as occupied
              for (let r = 0; r < rowspan; r++) {
                for (let c = 0; c < colspan; c++) {
                  if (gridOccupied[rowIndex + r]) {
                    gridOccupied[rowIndex + r][visualCol + c] = true;
                  }
                }
              }

              // Build colwidth array for all columns this cell spans
              let colwidth: number[] | null = null;
              if (widthInPixel) {
                colwidth = [];
                for (let i = 0; i < colspan; i++) {
                  const width = widthInPixel[visualCol + i];
                  if (width !== undefined) {
                    colwidth.push(width);
                  }
                }
                if (colwidth.length === 0) {
                  colwidth = null;
                }
              }

              colIdx += colspan;

              return {
                type:
                  (rowIndex === 0 && node.tableData?.rowHeader) ||
                  (visualCol === 0 && node.tableData?.columnHeader)
                    ? TIPTAP_TABLE_HEADER_CELL_TYPE
                    : Node_Type.TABLE_CELL,
                attrs: {
                  ...colNode.tableCellData,
                  id: colNode.id,
                  colwidth,
                },
                content: visit(colNode),
              };
            }),
          };
        }),
      };
    },
  },
  fromPm: {
    types: [Node_Type.TABLE],
    // @ts-ignore next node type
    convert: (node: PmNodeJson, visit: (node: PmNodeJson) => Node[]) => {
      const { attrs = {} } = node;
      const { id, dimensions, tableData: attrsTableData, animation } = attrs;

      // Handle both formats: attrs.tableData (new) or top-level attrs (legacy)
      const tableDataFromAttrs = attrsTableData || attrs;
      const {
        dimensions: _,
        cellPadding,
        animation: _hoisted, // hoisted to a top-level attr; never part of nested tableData
        ...restTableData
      } = tableDataFromAttrs as TableData;

      const tableNode: TableNode = {
        type: Node_Type.TABLE,
        id,
        // @ts-ignore next node type - data may be from legacy schema
        tableData: {
          ...restTableData,
          dimensions: {
            ...dimensions,
            rowsHeight: node.content?.map(node => node.attrs?.height),
          },
          // Only include cellPadding if it differs from defaults
          cellPadding:
            cellPadding?.length === 4 &&
            cellPadding?.every(
              (p: number, index: number) => p === TABLE_DEFAULTS.cellPadding[index]
            )
              ? undefined
              : cellPadding,
          ...(animation ? { animation } : {}),
        },
        nodes: visit(node) as TableRowNode[],
      };

      return tableNode;
    },
  },
};

export const tableRowConverter: PmNodeConverter = {
  toPm: {
    types: [Node_Type.TABLE_ROW],
    // @ts-ignore next node type
    convert: (node: TableRowNode, visit: (node: TableRowNode) => PmNodeJson[]) => ({
      type: Node_Type.TABLE_ROW,
      attrs: {
        id: node.id,
      },
      content: visit(node),
    }),
  },
  fromPm: {
    types: [Node_Type.TABLE_ROW],
    // @ts-ignore next node type
    convert: (node: PmNodeJson, visit: (node: PmNodeJson) => Node[]) => {
      const { attrs = {} } = node;
      const { id } = attrs;
      const nodes = visit(node);
      // Convert empty/undefined to empty array for consistency
      const cellNodes = (Array.isArray(nodes) && nodes.length > 0 ? nodes : []) as TableCellNode[];
      return {
        type: Node_Type.TABLE_ROW,
        id,
        ...(cellNodes.length > 0 && { nodes: cellNodes }),
      };
    },
  },
};

export const tableCellConverter: PmNodeConverter = {
  toPm: {
    types: [Node_Type.TABLE_CELL],
    // @ts-ignore next node type
    convert: (node: TableCellNode, visit: (node: TableCellNode) => PmNodeJson[]) => {
      return {
        type: Node_Type.TABLE_CELL,
        attrs: {
          id: node.id,
          ...node.tableCellData,
          colspan: node.tableCellData?.colspan || 1,
          rowspan: node.tableCellData?.rowspan || 1,
        },
        content: visit(node),
      };
    },
  },
  fromPm: {
    types: [TIPTAP_TABLE_HEADER_CELL_TYPE, Node_Type.TABLE_CELL],
    // @ts-ignore next node type
    convert: (node: PmNodeJson, visit: (node: PmNodeJson) => Node[]) => {
      const { attrs = {} } = node;
      const { id, colwidth: _, colspan, rowspan, ...data } = attrs;
      return {
        type: Node_Type.TABLE_CELL,
        id,
        tableCellData: {
          ...(data as TableCellData),
          ...(colspan > 1 && { colspan }),
          ...(rowspan > 1 && { rowspan }),
        },
        nodes: visit(node),
      };
    },
  },
};

const ratioWidthToPixel = (colsWidthRatio: $TSFixMe, colsMinWidth: $TSFixMe) => {
  if (colsWidthRatio && colsMinWidth) {
    return colsWidthRatio.map((width: number, i: number) => Math.max(width, colsMinWidth[i] || 0));
  }
};
