import React, { useContext, useMemo } from 'react';

import { RicosNodeContext, RicosNodeContextProvider } from './../../ricos-context/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

const TableRow = ({ node, nodeIndex, RicosNodesRenderer }: NodeViewRendererProps) => {
  const { parentNode } = useContext(RicosNodeContext);

  const rowIndex = useMemo(() => {
    const idx = parentNode?.nodes?.findIndex(row => row.id === node.id);
    return idx !== undefined && idx >= 0 ? idx : nodeIndex;
  }, [parentNode, node.id, nodeIndex]);

  const style = { height: parentNode?.tableData?.dimensions?.rowsHeight?.[rowIndex] || 'auto' };

  return (
    <tr style={style}>
      <RicosNodeContextProvider parentNode={parentNode} parentIndex={rowIndex}>
        <RicosNodesRenderer nodes={node.nodes ?? []} />
      </RicosNodeContextProvider>
    </tr>
  );
};

const TableRowRenderer = ({ node, ...props }: NodeViewRendererProps) => {
  return <TableRow key={node.id} node={node} {...props} />;
};

export default TableRowRenderer;
