import { CELL_MANUAL_MIN_WIDTH } from './consts.js';

export const TABLE_VERTICAL_PADDING = 16;

export const TABLE_DEFAULTS = {
  cellPadding: [10, 10, 10, 10],
  cellSpacing: 0,
} as const;

export const getDefaultCellPadding = (): number => TABLE_DEFAULTS.cellPadding[0];

export const normalizePadding = (padding: number[] | undefined, defaults: number[]) => {
  if (!padding || padding.length === 0) {
    return defaults;
  }

  if (padding.length === 1) {
    return [padding[0], padding[0], padding[0], padding[0]];
  }

  if (padding.length === 2) {
    return [padding[0], padding[1], padding[0], padding[1]];
  }

  if (padding.length === 3) {
    return [padding[0], padding[1], padding[2], padding[1]];
  }

  return padding;
};

export const getMinColumnWidthForPadding = (cellPadding: number[] | undefined): number => {
  const padding = normalizePadding(cellPadding, [...TABLE_DEFAULTS.cellPadding]);
  const paddingLeft = padding[3] ?? padding[1] ?? padding[0] ?? 10;
  const paddingRight = padding[1] ?? padding[0] ?? 10;
  const horizontalPadding = paddingLeft + paddingRight;
  const defaultHorizontalPadding = TABLE_DEFAULTS.cellPadding[1] + TABLE_DEFAULTS.cellPadding[3];
  return CELL_MANUAL_MIN_WIDTH + (horizontalPadding - defaultHorizontalPadding);
};
