/*
  Canonical border edit and sanitization logic.

  Key principles:
  - Canonical ownership: horizontal → top side, vertical → left side
  - Never duplicate styles to both sides
  - Only remap when coverage is exact (avoids overreach on misaligned spans)
  - Deterministic render precedence; no zIndex

  Exact coverage: the edited edge range equals the union of canonical opposite sides'
  cell ranges with no extra coverage or gaps.
*/

import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import type { Transaction } from './../../tiptap/pm/state.js';

import { TableMap } from '../tiptap/tablemap.js';
import type { CellPosition, Edge, Side } from './edge-detection.js';
import {
  buildCellGrid,
  computeHorizontalEdge,
  computeVerticalEdge,
  getAllSharedEdges,
  getCanonicalCells,
  getNonCanonicalCells,
  getOppositeSide,
  isCanonicalSide,
  isExactCoverage,
} from './edge-detection.js';

interface BorderStyle {
  color?: string;
  width?: number;
}

interface CellBorderUpdate {
  pos: number;
  borderColors?: Record<string, string | undefined>;
  borderWidths?: Record<string, number | undefined>;
}

function isExplicitBorder(
  cell: ProseMirrorNode,
  side: Side
): { hasColor: boolean; hasWidth: boolean } {
  const hasColor = cell.attrs.borderColors?.[side] !== undefined;
  const hasWidth = cell.attrs.borderWidths?.[side] !== undefined;
  return { hasColor, hasWidth };
}

function getBorderStyle(cell: ProseMirrorNode, side: Side): BorderStyle {
  return {
    color: cell.attrs.borderColors?.[side],
    width: cell.attrs.borderWidths?.[side],
  };
}

function borderStylesEqual(a: BorderStyle, b: BorderStyle): boolean {
  return a.color === b.color && a.width === b.width;
}

function hasUniformBorderStyle(
  cells: CellPosition[],
  side: Side,
  targetStyle: BorderStyle
): boolean {
  if (cells.length === 0) {
    return false;
  }

  return cells.every(cell => {
    const cellStyle = getBorderStyle(cell.node, side);
    return borderStylesEqual(cellStyle, targetStyle);
  });
}

function allCellsHaveDefaultBorder(cells: CellPosition[], side: Side): boolean {
  return cells.every(cell => {
    const explicit = isExplicitBorder(cell.node, side);
    return !explicit.hasColor && !explicit.hasWidth;
  });
}

function getEdgeRange(edge: Edge): { start: number; end: number } {
  return edge.orientation === 'horizontal' ? edge.colRange : edge.rowRange;
}

function getCellRange(cell: CellPosition, edge: Edge): { start: number; end: number } {
  if (edge.orientation === 'horizontal') {
    return { start: cell.col, end: cell.col + cell.colspan };
  } else {
    return { start: cell.row, end: cell.row + cell.rowspan };
  }
}

function isCellFullyContained(
  cell: CellPosition,
  edgeStart: number,
  edgeEnd: number,
  edge: Edge
): boolean {
  const { start: cellStart, end: cellEnd } = getCellRange(cell, edge);
  return cellStart >= edgeStart && cellEnd <= edgeEnd;
}

function setBorderStyle(update: CellBorderUpdate, side: Side, style: BorderStyle): void {
  if (style.color !== undefined) {
    update.borderColors![side] = style.color;
  }
  if (style.width !== undefined) {
    update.borderWidths![side] = style.width;
  }
}

function clearBorderStyle(update: CellBorderUpdate, side: Side): void {
  update.borderColors![side] = undefined;
  update.borderWidths![side] = undefined;
}

function applyBorderStyleToCell(
  cell: CellPosition,
  side: Side,
  style: BorderStyle,
  clear: boolean,
  updates: Map<number, CellBorderUpdate>
): void {
  const update = getOrCreateUpdate(updates, cell.pos, cell.node);
  if (clear) {
    clearBorderStyle(update, side);
  } else {
    setBorderStyle(update, side, style);
  }
}

export function extractCellPositions(
  tableNode: ProseMirrorNode,
  tableStart: number
): { cells: CellPosition[]; width: number; height: number } {
  const map = TableMap.get(tableNode);
  const cells: CellPosition[] = [];
  const seen = new Set<number>();

  let _rowIndex = 0;
  tableNode.forEach((rowNode, rowOffset) => {
    if (rowNode.type.spec.tableRole === 'row') {
      let _colIndex = 0;
      rowNode.forEach((cellNode, cellOffset) => {
        if (
          cellNode.type.spec.tableRole === 'cell' ||
          cellNode.type.spec.tableRole === 'header_cell'
        ) {
          const cellPos = tableStart + rowOffset + cellOffset + 1;

          if (!seen.has(cellPos)) {
            seen.add(cellPos);

            const placement = map.findCell(cellPos - tableStart);

            cells.push({
              pos: cellPos,
              node: cellNode,
              row: placement.row,
              col: placement.col,
              rowspan: placement.rowspan,
              colspan: placement.colspan,
            });
          }
        }
        _colIndex++;
      });
      _rowIndex++;
    }
  });

  return { cells, width: map.width, height: map.height };
}

export function applyBorderEdit(
  tr: Transaction,
  tableNode: ProseMirrorNode,
  tableStart: number,
  selectedCells: { node: ProseMirrorNode; pos: number }[],
  side: Side | null,
  style: BorderStyle,
  clear: boolean = false
): void {
  const { cells, width, height } = extractCellPositions(tableNode, tableStart);
  const grid = buildCellGrid(cells, width, height);

  const selectedPositions = new Set(selectedCells.map(c => c.pos));
  const selectedCellsData = cells.filter(c => selectedPositions.has(c.pos));

  const cellSpacing = (tableNode.attrs.tableData?.cellSpacing as number | undefined) ?? 0;

  // With spacing, cells have independent borders - no canonical remapping
  if (cellSpacing > 0) {
    const updates = new Map<number, CellBorderUpdate>();
    const sidesToUpdate: Side[] = side === null ? ['top', 'bottom', 'left', 'right'] : [side];

    for (const cell of selectedCellsData) {
      for (const s of sidesToUpdate) {
        applyBorderStyleToCell(cell, s, style, clear, updates);
      }
    }
    applyUpdates(tr, updates);
    return;
  }

  // Collapsed borders: use canonical remapping logic
  if (side === null) {
    applyBorderToAllSides(tr, selectedCellsData, grid, width, height, style, clear);
  } else {
    const updates = new Map<number, CellBorderUpdate>();
    applyBorderToSide(tr, selectedCellsData, side, grid, width, height, style, clear, updates);
    applyUpdates(tr, updates);
  }
}

function applyBorderToAllSides(
  tr: Transaction,
  selectedCells: CellPosition[],
  grid: CellPosition[][],
  _width: number,
  _height: number,
  style: BorderStyle,
  clear: boolean
): void {
  const updates = new Map<number, CellBorderUpdate>();
  const sides: Side[] = ['top', 'bottom', 'left', 'right'];
  for (const side of sides) {
    applyBorderToSide(tr, selectedCells, side, grid, _width, _height, style, clear, updates);
  }
  applyUpdates(tr, updates);
}

function applyBorderToSide(
  _tr: Transaction,
  selectedCells: CellPosition[],
  side: Side,
  grid: CellPosition[][],
  width: number,
  height: number,
  style: BorderStyle,
  clear: boolean,
  updates: Map<number, CellBorderUpdate>
): void {
  const canonical = isCanonicalSide(side);

  const edgeMap = new Map<string, CellPosition[]>();

  for (const cell of selectedCells) {
    const edgeKey = getEdgeKey(cell, side);
    if (!edgeMap.has(edgeKey)) {
      edgeMap.set(edgeKey, []);
    }
    edgeMap.get(edgeKey)!.push(cell);
  }

  for (const [_edgeKey, cellsOnEdge] of edgeMap.entries()) {
    const edge = computeEdgeFromCells(cellsOnEdge, side, grid, width, height);
    if (!edge) {
      continue;
    }

    if (canonical) {
      applyCanonicalEdit(cellsOnEdge, side, edge, style, clear, updates);
    } else {
      applyNonCanonicalEdit(cellsOnEdge, side, edge, style, clear, updates);
    }
  }
}

function applyCanonicalEdit(
  cells: CellPosition[],
  side: Side,
  edge: Edge,
  style: BorderStyle,
  clear: boolean,
  updates: Map<number, CellBorderUpdate>
): void {
  const oppositeSide = getOppositeSide(side);
  const oppositeCells = getNonCanonicalCells(edge);

  for (const cell of cells) {
    applyBorderStyleToCell(cell, side, style, clear, updates);
  }

  // Also apply the same style to the opposite side of neighboring cells
  // This ensures both sides of the shared edge have the same color
  if (!clear && oppositeCells.length > 0) {
    const { start: edgeStart, end: edgeEnd } = getEdgeRange(edge);
    for (const cell of oppositeCells) {
      if (isCellFullyContained(cell, edgeStart, edgeEnd, edge)) {
        applyBorderStyleToCell(cell, oppositeSide, style, false, updates);
      }
    }
  }
}

function applyNonCanonicalEdit(
  cells: CellPosition[],
  side: Side,
  edge: Edge,
  style: BorderStyle,
  clear: boolean,
  updates: Map<number, CellBorderUpdate>
): void {
  const canonicalSide = getOppositeSide(side);
  const canonicalCells = getCanonicalCells(edge);
  const { start: edgeStart, end: edgeEnd } = getEdgeRange(edge);
  const exactCoverage = isExactCoverage(edge);

  if (exactCoverage && !clear) {
    // Exact coverage: set both sides to the same style
    for (const cell of canonicalCells) {
      applyBorderStyleToCell(cell, canonicalSide, style, false, updates);
    }

    for (const cell of cells) {
      applyBorderStyleToCell(cell, side, style, false, updates);
    }
  } else if (exactCoverage && clear) {
    // Clearing with exact coverage
    const canonicalHasDuplicate =
      hasUniformBorderStyle(cells, side, { color: undefined, width: undefined }) ||
      hasUniformBorderStyle(canonicalCells, canonicalSide, getBorderStyle(cells[0].node, side));

    for (const cell of cells) {
      const update = getOrCreateUpdate(updates, cell.pos, cell.node);
      clearBorderStyle(update, side);
    }

    if (canonicalHasDuplicate) {
      for (const cell of canonicalCells) {
        const update = getOrCreateUpdate(updates, cell.pos, cell.node);
        clearBorderStyle(update, canonicalSide);
      }
    }
  } else {
    // No exact coverage: write to non-canonical, and also set fully contained canonical cells
    for (const cell of cells) {
      applyBorderStyleToCell(cell, side, style, clear, updates);
    }

    if (!clear) {
      // Set the canonical side of neighboring cells to the same style
      for (const cell of canonicalCells) {
        if (isCellFullyContained(cell, edgeStart, edgeEnd, edge)) {
          applyBorderStyleToCell(cell, canonicalSide, style, false, updates);
        }
      }
    }
  }
}

function getEdgeKey(cell: CellPosition, side: Side): string {
  switch (side) {
    case 'top':
      return `h:${cell.row}:${cell.col}:${cell.col + cell.colspan}`;
    case 'bottom':
      return `h:${cell.row + cell.rowspan}:${cell.col}:${cell.col + cell.colspan}`;
    case 'left':
      return `v:${cell.col}:${cell.row}:${cell.row + cell.rowspan}`;
    case 'right':
      return `v:${cell.col + cell.colspan}:${cell.row}:${cell.row + cell.rowspan}`;
    default:
      return '';
  }
}

function computeEdgeFromCells(
  cells: CellPosition[],
  side: Side,
  grid: CellPosition[][],
  _width: number,
  _height: number
): Edge | null {
  if (cells.length === 0) {
    return null;
  }

  if (side === 'top' || side === 'bottom') {
    let minCol = Infinity;
    let maxCol = -Infinity;
    let rowEdgeIndex = -1;

    for (const cell of cells) {
      minCol = Math.min(minCol, cell.col);
      maxCol = Math.max(maxCol, cell.col + cell.colspan);
      rowEdgeIndex = side === 'top' ? cell.row : cell.row + cell.rowspan;
    }

    return computeHorizontalEdge(grid, rowEdgeIndex, minCol, maxCol, side);
  } else {
    let minRow = Infinity;
    let maxRow = -Infinity;
    let colEdgeIndex = -1;

    for (const cell of cells) {
      minRow = Math.min(minRow, cell.row);
      maxRow = Math.max(maxRow, cell.row + cell.rowspan);
      colEdgeIndex = side === 'left' ? cell.col : cell.col + cell.colspan;
    }

    return computeVerticalEdge(grid, colEdgeIndex, minRow, maxRow, side);
  }
}

function getOrCreateUpdate(
  updates: Map<number, CellBorderUpdate>,
  pos: number,
  node: ProseMirrorNode
): CellBorderUpdate {
  if (!updates.has(pos)) {
    updates.set(pos, {
      pos,
      borderColors: { ...(node.attrs.borderColors || {}) },
      borderWidths: { ...(node.attrs.borderWidths || {}) },
    });
  }
  return updates.get(pos)!;
}

function applyUpdates(tr: Transaction, updates: Map<number, CellBorderUpdate>): void {
  for (const update of updates.values()) {
    const node = tr.doc.nodeAt(update.pos);
    if (!node) {
      continue;
    }

    tr.setNodeMarkup(update.pos, null, {
      ...node.attrs,
      borderColors: update.borderColors,
      borderWidths: update.borderWidths,
    });
  }
}

/**
 * Canonicalize all borders in a table after structural changes.
 * Removes duplicate borders and remaps non-canonical to canonical where possible.
 */
export function canonicalizeBorders(
  tr: Transaction,
  tableNode: ProseMirrorNode,
  tableStart: number
): void {
  const cellSpacing = (tableNode.attrs.tableData?.cellSpacing as number | undefined) ?? 0;
  if (cellSpacing > 0) {
    return;
  }

  const { cells, width, height } = extractCellPositions(tableNode, tableStart);
  const grid = buildCellGrid(cells, width, height);
  const updates = new Map<number, CellBorderUpdate>();

  const allEdges = getAllSharedEdges(grid, width, height);

  for (const edge of allEdges) {
    canonicalizeEdge(edge, updates);
  }

  applyUpdates(tr, updates);
}

function canonicalizeEdge(edge: Edge, updates: Map<number, CellBorderUpdate>): void {
  const canonicalCells = getCanonicalCells(edge);
  const nonCanonicalCells = getNonCanonicalCells(edge);

  if (canonicalCells.length === 0 || nonCanonicalCells.length === 0) {
    return;
  }

  const canonicalSide = edge.canonicalSide;
  const nonCanonicalSide = getOppositeSide(canonicalSide);

  const canonicalStyles = canonicalCells.map(c => getBorderStyle(c.node, canonicalSide));
  const nonCanonicalStyles = nonCanonicalCells.map(c => getBorderStyle(c.node, nonCanonicalSide));

  const canonicalUniform = canonicalStyles.every(s => borderStylesEqual(s, canonicalStyles[0]));
  const nonCanonicalUniform = nonCanonicalStyles.every(s =>
    borderStylesEqual(s, nonCanonicalStyles[0])
  );

  // Both sides explicit and equal: keep canonical, clear non-canonical
  if (canonicalUniform && nonCanonicalUniform) {
    const canonicalStyle = canonicalStyles[0];
    const nonCanonicalStyle = nonCanonicalStyles[0];

    const bothExplicit =
      (canonicalStyle.color !== undefined || canonicalStyle.width !== undefined) &&
      (nonCanonicalStyle.color !== undefined || nonCanonicalStyle.width !== undefined);

    if (bothExplicit && borderStylesEqual(canonicalStyle, nonCanonicalStyle)) {
      for (const cell of nonCanonicalCells) {
        const update = getOrCreateUpdate(updates, cell.pos, cell.node);
        clearBorderStyle(update, nonCanonicalSide);
      }
    }
  }

  // Canonical default, non-canonical explicit with exact coverage: remap
  if (isExactCoverage(edge)) {
    const canonicalAllDefault = allCellsHaveDefaultBorder(canonicalCells, canonicalSide);

    if (canonicalAllDefault && nonCanonicalUniform) {
      const nonCanonicalStyle = nonCanonicalStyles[0];
      const nonCanonicalExplicit =
        nonCanonicalStyle.color !== undefined || nonCanonicalStyle.width !== undefined;

      if (nonCanonicalExplicit) {
        for (const cell of canonicalCells) {
          const update = getOrCreateUpdate(updates, cell.pos, cell.node);
          setBorderStyle(update, canonicalSide, nonCanonicalStyle);
        }

        for (const cell of nonCanonicalCells) {
          const update = getOrCreateUpdate(updates, cell.pos, cell.node);
          clearBorderStyle(update, nonCanonicalSide);
        }
      }
    }
  }
}
