import React, { createContext, useContext, useMemo } from 'react';

import type { TableNode } from './../../ricos-schema/next-schema/index.js';

import type { BorderPadding, CellBorders, ResolvedBordersMap } from './resolve-cell-borders.js';
import { calculateBorderPadding, resolveCellBorders } from './resolve-cell-borders.js';

interface TableBordersContextValue {
  borders: ResolvedBordersMap;
  cellSpacing: number;
  isRTL: boolean;
  borderPadding: BorderPadding;
}

const TableBordersContext = createContext<TableBordersContextValue | null>(null);

interface TableBordersProviderProps {
  tableNode: TableNode;
  isRTL: boolean;
  children: React.ReactNode;
}

export const TableBordersProvider: React.FC<TableBordersProviderProps> = ({
  tableNode,
  isRTL,
  children,
}) => {
  const cellSpacing = (tableNode.tableData?.cellSpacing as number | undefined) ?? 0;

  const value = useMemo((): TableBordersContextValue => {
    let borders: ResolvedBordersMap;
    try {
      borders = resolveCellBorders(tableNode, { drawDefaultGrid: true, cellSpacing });
    } catch (e) {
      // Border resolution can throw on malformed content (e.g. a ragged table).
      // Fall back to an empty map so the table still renders with default cell
      // borders instead of crashing the whole viewer, and log so the bad content
      // stays diagnosable.
      console.error('Failed to resolve table cell borders', e);
      borders = new Map();
    }
    const borderPadding = calculateBorderPadding(tableNode);
    return { borders, cellSpacing, isRTL, borderPadding };
  }, [tableNode, cellSpacing, isRTL]);

  return <TableBordersContext.Provider value={value}>{children}</TableBordersContext.Provider>;
};

export function useCellBorders(cellId: string): CellBorders | null {
  const context = useContext(TableBordersContext);
  if (!context) {
    return null;
  }
  return context.borders.get(cellId) || null;
}

export function useTableBordersContext(): TableBordersContextValue | null {
  return useContext(TableBordersContext);
}
