/*
  Edge detection and coverage utilities for canonical border management.

  Core concepts:
  - Horizontal edges: canonical ownership is top side
  - Vertical edges: canonical ownership is left side
  - Exact coverage: opposite cells' spans union equals the edited range with no gaps/overflow
*/

import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';

export type Side = 'top' | 'bottom' | 'left' | 'right';
export type Orientation = 'horizontal' | 'vertical';

export interface CellPosition {
  pos: number;
  node: ProseMirrorNode;
  row: number;
  col: number;
  rowspan: number;
  colspan: number;
}

export interface EdgeRange {
  start: number;
  end: number;
}

export interface HorizontalEdge {
  orientation: 'horizontal';
  rowEdgeIndex: number;
  colRange: EdgeRange;
  canonicalSide: 'top' | 'bottom';
  aboveCells: CellPosition[];
  belowCells: CellPosition[];
}

export interface VerticalEdge {
  orientation: 'vertical';
  colEdgeIndex: number;
  rowRange: EdgeRange;
  canonicalSide: 'left' | 'right';
  leftCells: CellPosition[];
  rightCells: CellPosition[];
}

export type Edge = HorizontalEdge | VerticalEdge;

export function buildCellGrid(
  tableCells: CellPosition[],
  tableWidth: number,
  tableHeight: number
): CellPosition[][] {
  const grid: CellPosition[][] = Array(tableHeight)
    .fill(null)
    .map(() => Array(tableWidth).fill(null));

  for (const cell of tableCells) {
    for (let r = cell.row; r < cell.row + cell.rowspan; r++) {
      for (let c = cell.col; c < cell.col + cell.colspan; c++) {
        if (r < tableHeight && c < tableWidth) {
          grid[r][c] = cell;
        }
      }
    }
  }

  return grid;
}

export function getCellAt(grid: CellPosition[][], row: number, col: number): CellPosition | null {
  if (row < 0 || row >= grid.length || col < 0 || col >= grid[0]?.length) {
    return null;
  }
  return grid[row][col] || null;
}

function collectUniqueCells(
  grid: CellPosition[][],
  indices: number[],
  getCell: (idx: number) => CellPosition | null,
  shouldInclude: (cell: CellPosition, idx: number) => boolean
): CellPosition[] {
  const cells: CellPosition[] = [];
  const seen = new Set<number>();

  for (const idx of indices) {
    const cell = getCell(idx);
    if (cell && !seen.has(cell.pos) && shouldInclude(cell, idx)) {
      cells.push(cell);
      seen.add(cell.pos);
    }
  }

  return cells;
}

export function computeHorizontalEdge(
  grid: CellPosition[][],
  rowEdgeIndex: number,
  colStart: number,
  colEnd: number,
  _side: 'top' | 'bottom'
): HorizontalEdge {
  const tableHeight = grid.length;
  const tableWidth = grid[0]?.length || 0;
  const columns = Array.from({ length: colEnd - colStart }, (_, i) => colStart + i).filter(
    c => c < tableWidth
  );

  const aboveCells =
    rowEdgeIndex > 0
      ? collectUniqueCells(
          grid,
          columns,
          c => getCellAt(grid, rowEdgeIndex - 1, c),
          (cell, _) => cell.row + cell.rowspan === rowEdgeIndex
        )
      : [];

  const belowCells =
    rowEdgeIndex < tableHeight
      ? collectUniqueCells(
          grid,
          columns,
          c => getCellAt(grid, rowEdgeIndex, c),
          (cell, _) => cell.row === rowEdgeIndex
        )
      : [];

  return {
    orientation: 'horizontal',
    rowEdgeIndex,
    colRange: { start: colStart, end: colEnd },
    canonicalSide: 'top',
    aboveCells,
    belowCells,
  };
}

export function computeVerticalEdge(
  grid: CellPosition[][],
  colEdgeIndex: number,
  rowStart: number,
  rowEnd: number,
  _side: 'left' | 'right'
): VerticalEdge {
  const tableHeight = grid.length;
  const tableWidth = grid[0]?.length || 0;
  const rows = Array.from({ length: rowEnd - rowStart }, (_, i) => rowStart + i).filter(
    r => r < tableHeight
  );

  const leftCells =
    colEdgeIndex > 0
      ? collectUniqueCells(
          grid,
          rows,
          r => getCellAt(grid, r, colEdgeIndex - 1),
          (cell, _) => cell.col + cell.colspan === colEdgeIndex
        )
      : [];

  const rightCells =
    colEdgeIndex < tableWidth
      ? collectUniqueCells(
          grid,
          rows,
          r => getCellAt(grid, r, colEdgeIndex),
          (cell, _) => cell.col === colEdgeIndex
        )
      : [];

  return {
    orientation: 'vertical',
    colEdgeIndex,
    rowRange: { start: rowStart, end: rowEnd },
    canonicalSide: 'left',
    leftCells,
    rightCells,
  };
}

/**
 * Check if canonical cells exactly match the edited range (no gaps, no overreach).
 * Required for remapping non-canonical to canonical.
 */
export function isExactCoverage(edge: Edge): boolean {
  const canonicalCells = getCanonicalCells(edge);
  if (canonicalCells.length === 0) {
    return false;
  }

  const isHorizontal = edge.orientation === 'horizontal';
  const { start: rangeStart, end: rangeEnd } = isHorizontal ? edge.colRange : edge.rowRange;

  // Get union of canonical cells' spans
  let canonicalMin = Infinity;
  let canonicalMax = -Infinity;

  for (const cell of canonicalCells) {
    const cellStart = isHorizontal ? cell.col : cell.row;
    const cellEnd = isHorizontal ? cell.col + cell.colspan : cell.row + cell.rowspan;
    canonicalMin = Math.min(canonicalMin, cellStart);
    canonicalMax = Math.max(canonicalMax, cellEnd);
  }

  // Check if ranges match exactly
  if (canonicalMin !== rangeStart || canonicalMax !== rangeEnd) {
    return false;
  }

  // Verify no gaps
  const covered = new Array(rangeEnd - rangeStart).fill(false);

  for (const cell of canonicalCells) {
    const cellStart = isHorizontal ? cell.col : cell.row;
    const cellEnd = isHorizontal ? cell.col + cell.colspan : cell.row + cell.rowspan;
    const clampedStart = Math.max(cellStart, rangeStart);
    const clampedEnd = Math.min(cellEnd, rangeEnd);

    for (let i = clampedStart; i < clampedEnd; i++) {
      const idx = i - rangeStart;
      if (idx >= 0 && idx < covered.length) {
        covered[idx] = true;
      }
    }
  }

  return covered.every(c => c);
}

export function getAllSharedEdges(
  grid: CellPosition[][],
  tableWidth: number,
  tableHeight: number
): Edge[] {
  const edges: Edge[] = [];

  for (let rowEdge = 1; rowEdge < tableHeight; rowEdge++) {
    const edgeSegments = getHorizontalEdgeSegments(grid, rowEdge, tableWidth);
    for (const segment of edgeSegments) {
      const edge = computeHorizontalEdge(grid, rowEdge, segment.start, segment.end, 'top');
      if (edge.aboveCells.length > 0 && edge.belowCells.length > 0) {
        edges.push(edge);
      }
    }
  }

  for (let colEdge = 1; colEdge < tableWidth; colEdge++) {
    const edgeSegments = getVerticalEdgeSegments(grid, colEdge, tableHeight);
    for (const segment of edgeSegments) {
      const edge = computeVerticalEdge(grid, colEdge, segment.start, segment.end, 'left');
      if (edge.leftCells.length > 0 && edge.rightCells.length > 0) {
        edges.push(edge);
      }
    }
  }

  return edges;
}

function getEdgeSegments(length: number, checkSharedEdge: (idx: number) => boolean): EdgeRange[] {
  const segments: EdgeRange[] = [];
  let segmentStart = 0;

  for (let i = 0; i < length; i++) {
    if (!checkSharedEdge(i) && i > segmentStart) {
      segments.push({ start: segmentStart, end: i });
      segmentStart = i;
    }
  }

  if (length > segmentStart) {
    segments.push({ start: segmentStart, end: length });
  }

  return segments.filter(s => s.end > s.start);
}

function getHorizontalEdgeSegments(
  grid: CellPosition[][],
  rowEdgeIndex: number,
  tableWidth: number
): EdgeRange[] {
  return getEdgeSegments(tableWidth, c => {
    const cellAbove = rowEdgeIndex > 0 ? getCellAt(grid, rowEdgeIndex - 1, c) : null;
    const cellBelow = rowEdgeIndex < grid.length ? getCellAt(grid, rowEdgeIndex, c) : null;

    return !!(
      cellAbove &&
      cellBelow &&
      cellAbove.pos !== cellBelow.pos &&
      cellAbove.row + cellAbove.rowspan === rowEdgeIndex &&
      cellBelow.row === rowEdgeIndex
    );
  });
}

function getVerticalEdgeSegments(
  grid: CellPosition[][],
  colEdgeIndex: number,
  tableHeight: number
): EdgeRange[] {
  return getEdgeSegments(tableHeight, r => {
    const cellLeft = colEdgeIndex > 0 ? getCellAt(grid, r, colEdgeIndex - 1) : null;
    const cellRight =
      colEdgeIndex < (grid[0]?.length || 0) ? getCellAt(grid, r, colEdgeIndex) : null;

    return !!(
      cellLeft &&
      cellRight &&
      cellLeft.pos !== cellRight.pos &&
      cellLeft.col + cellLeft.colspan === colEdgeIndex &&
      cellRight.col === colEdgeIndex
    );
  });
}

export function isCanonicalSide(side: Side): boolean {
  return side === 'top' || side === 'left';
}

export function getOppositeSide(side: Side): Side {
  switch (side) {
    case 'top':
      return 'bottom';
    case 'bottom':
      return 'top';
    case 'left':
      return 'right';
    case 'right':
      return 'left';
    default:
      return 'top';
  }
}

export function getCanonicalCells(edge: Edge): CellPosition[] {
  if (edge.orientation === 'horizontal') {
    return edge.canonicalSide === 'top' ? edge.belowCells : edge.aboveCells;
  } else {
    return edge.canonicalSide === 'left' ? edge.rightCells : edge.leftCells;
  }
}

export function getNonCanonicalCells(edge: Edge): CellPosition[] {
  if (edge.orientation === 'horizontal') {
    return edge.canonicalSide === 'top' ? edge.aboveCells : edge.belowCells;
  } else {
    return edge.canonicalSide === 'left' ? edge.leftCells : edge.rightCells;
  }
}

type CellLike = { row: number; col: number; rowspan: number; colspan: number };

/**
 * Whether `cell`'s `side` is on the outside boundary of a selection — either
 * the table edge or the neighbouring cell is not part of the selection.
 */
export function isCellOuterEdge(
  cell: CellLike,
  side: Side,
  tableWidth: number,
  tableHeight: number,
  isCellInSelection: (row: number, col: number) => boolean
): boolean {
  switch (side) {
    case 'top':
      return cell.row === 0 || !isCellInSelection(cell.row - 1, cell.col);
    case 'bottom':
      return (
        cell.row + cell.rowspan >= tableHeight ||
        !isCellInSelection(cell.row + cell.rowspan, cell.col)
      );
    case 'left':
      return cell.col === 0 || !isCellInSelection(cell.row, cell.col - 1);
    case 'right':
      return (
        cell.col + cell.colspan >= tableWidth ||
        !isCellInSelection(cell.row, cell.col + cell.colspan)
      );
    default:
      return false;
  }
}

const OUTER_SIDES: readonly Side[] = ['top', 'bottom', 'left', 'right'];

/**
 * Groups selected cells by which outer side of the selection they own.
 * Each cell can appear under multiple sides (corner cells on top + left, etc.).
 * Decoupled from PM types via `getCellData` so callers can pass any entry shape.
 */
export function groupOuterEdgeCells<T>(
  selected: readonly T[],
  getCellData: (entry: T) => CellLike | undefined,
  tableWidth: number,
  tableHeight: number,
  isCellInSelection: (row: number, col: number) => boolean
): Map<Side, T[]> {
  const grouped: Map<Side, T[]> = new Map(OUTER_SIDES.map(side => [side, []]));
  for (const entry of selected) {
    const cellData = getCellData(entry);
    if (!cellData) {
      continue;
    }
    for (const side of OUTER_SIDES) {
      if (isCellOuterEdge(cellData, side, tableWidth, tableHeight, isCellInSelection)) {
        grouped.get(side)!.push(entry);
      }
    }
  }
  return grouped;
}
