import type { RicosServices, ToolbarButton } from './../ricos-types/index.js';
import { createAnimationButton } from './../_shared/plugin-toolbar/create-animation-button.js';
import { createSeparator } from './../_shared/plugin-toolbar/separator/create-separator.js';

import {
  createBackgroundColorButton,
  createBorderButton,
  createContextButton,
  createInsertButton,
  createMergeCellsButton,
  createMoveColumnLeftButton,
  createMoveColumnRightButton,
  createMoveRowDownButton,
  createMoveRowUpButton,
  createSpacingButton,
  createSplitCellButton,
  createTextAlignmentButton,
} from './toolbar/buttons/index.js';
import { createVerticalAlignmentButton } from './toolbar/buttons/vertical-alignment-button.js';
import { getTableForAnimation } from './toolbar/get-table-for-animation.js';
import type { TablePluginEditorConfig } from './types.js';

export const getToolbarButtons = (
  _: TablePluginEditorConfig,
  services: RicosServices
): ToolbarButton[] => {
  const backgroundColorButton = createBackgroundColorButton(services);
  const borderButton = createBorderButton(services);
  const textAlignmentButton = createTextAlignmentButton(services);
  const verticalAlignmentButton = createVerticalAlignmentButton(services);
  const insertButton = createInsertButton(services);
  const moveColumnLeftButton = createMoveColumnLeftButton();
  const moveColumnRightButton = createMoveColumnRightButton();
  const moveRowUpButton = createMoveRowUpButton();
  const moveRowDownButton = createMoveRowDownButton();
  const mergeCellsButton = createMergeCellsButton();
  const splitCellButton = createSplitCellButton();
  const spacingButton = createSpacingButton(services);
  // animation applies to the whole table — visible for the table NodeSelection
  // or a whole-table cell selection, hidden on partial cell selections
  const animation = createAnimationButton(services, getTableForAnimation);
  const contextButton = createContextButton(services);

  if (services.context.environment === 'wixel') {
    return [
      backgroundColorButton,
      borderButton,
      textAlignmentButton,
      verticalAlignmentButton,
      insertButton,
      moveColumnLeftButton,
      moveColumnRightButton,
      moveRowUpButton,
      moveRowDownButton,
      mergeCellsButton,
      splitCellButton,
      spacingButton,
      animation,
      contextButton,
    ];
  }

  const separator = createSeparator();

  return [
    backgroundColorButton,
    separator,
    borderButton,
    textAlignmentButton,
    verticalAlignmentButton,
    insertButton,
    moveColumnLeftButton,
    moveColumnRightButton,
    moveRowUpButton,
    moveRowDownButton,
    mergeCellsButton,
    splitCellButton,
    spacingButton,
    animation,
    separator,
    contextButton,
  ];
};
